export const STORAGE_KEY='storybank.public.prototype.v1';
export const MAX_REFERENCES=15;
export const traits=['Conversational','Short paragraphs','Story first','Specific examples','Reflective','Practical','Curious questions','Low-key CTA'];
export function uid(prefix='item'){return `${prefix}_${globalThis.crypto.randomUUID()}`;}
export function plainText(text){return String(text).replace(/\*\*(.*?)\*\*/gs,'$1').replace(/(?<!\*)\*([^*]+)\*(?!\*)/gs,'$1').trim();}
export function safeUrl(value){try{const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password)throw Error();return u.href;}catch{throw Error('Use a complete https:// URL with no embedded credentials.');}}
export function normalizeReference(data){const name=String(data.name||'').trim();if(!name)throw Error('Give this reference a name.');return {id:uid('ref'),name:name.slice(0,80),url:String(data.url||'').trim()?safeUrl(data.url):'',notes:String(data.notes||'').trim().slice(0,800)};}
export function createOutline(story,style){
 const source=String(story.body||'').trim();if(!source)throw Error('Add a written story or an edited transcript first.');
 if(!story.rights)throw Error('Confirm that this is your story or material you are authorized to use.');
 if(source.length>3000)throw Error('This note is too long for one post. Shorten it before creating an outline.');
 const body=style.structure==='lesson'?`${story.title.trim()}\n\n${source}`:source;
 return {id:uid('draft'),storyId:story.id,title:story.title,body,sourceSnapshot:source,sourceTitle:story.title,mode:'outline',createdAt:new Date().toISOString(),updatedAt:new Date().toISOString(),approval:null,reviewed:false};
}
export async function fingerprint(text){if(!globalThis.crypto?.subtle)throw Error('Approval requires a secure browser context (HTTPS or localhost).');const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(plainText(text)));return [...new Uint8Array(digest)].map(x=>x.toString(16).padStart(2,'0')).join('');}
export function editDraft(state,id,body){const d=state.drafts.find(x=>x.id===id);if(!d)throw Error('Draft not found.');if(d.body===body)return d;d.body=body;d.approval=null;d.reviewed=false;d.updatedAt=new Date().toISOString();for(const p of state.plans){if(p.draftId===id&&p.status==='planned'){p.status='cancelled';p.reason='Draft changed after approval.';}}return d;}
export function validateApproval(draft){const text=plainText(draft.body);if(!text)throw Error('Write something before approving.');if(text.length>3000)throw Error('Keep the plain-text post at 3,000 characters or fewer.');if(!draft.reviewed)throw Error('Review the facts and confirm the checklist first.');if(/\[(?:add|insert|your|todo|placeholder)/i.test(text))throw Error('Replace draft placeholders before approval.');}
export function planDraft(state,draftId,timeISO,hash,now=Date.now()){
 const draft=state.drafts.find(d=>d.id===draftId);if(!draft?.approval||draft.approval.hash!==hash)throw Error('Approve this exact version before planning it.');
 const t=Date.parse(timeISO);if(!Number.isFinite(t)||t<=now)throw Error('Choose a future date and time.');
 if(state.plans.some(p=>p.status==='planned'&&(p.draftId===draftId||p.hash===hash)))throw Error('This version already has an active plan. Cancel it before creating another.');
 const plan={id:uid('plan'),draftId,timeISO:new Date(t).toISOString(),hash,status:'planned',createdAt:new Date(now).toISOString()};state.plans.push(plan);return plan;
}
export function deleteStory(state,id){const draftIds=new Set(state.drafts.filter(d=>d.storyId===id).map(d=>d.id));state.stories=state.stories.filter(s=>s.id!==id);state.drafts=state.drafts.filter(d=>!draftIds.has(d.id));state.plans=state.plans.filter(p=>!draftIds.has(p.draftId));}
export function freshState(){return {version:1,onboarded:false,profile:{name:'',headline:''},style:{structure:'story',tone:'Warm & grounded',traits:['Conversational','Short paragraphs','Specific examples'],avoid:'Hype, invented numbers, and generic motivational advice.'},references:[],stories:[],drafts:[],plans:[]};}
export function examples(){return [{id:uid('story'),title:'The question that changed the brief',body:'During a project kickoff, I asked the client what they wanted their customer to do next. We had been discussing colours and layouts. That one question brought us back to the purpose of the page. I wrote it at the top of my brief so I would keep coming back to it.',tag:'Work moment',rights:true,demo:true,createdAt:new Date().toISOString(),audioId:null},{id:uid('story'),title:'A lesson from my first rough draft',body:'I kept editing the first sentence before I had written the rest. When I finally put a rough version on the page, I could see what the story was actually about. Now I try to finish the thought before polishing the opening.',tag:'Something learned',rights:true,demo:true,createdAt:new Date().toISOString(),audioId:null}];}
export function readState(storage){try{const value=JSON.parse(storage.getItem(STORAGE_KEY));if(value?.version===1&&['stories','drafts','plans','references'].every(k=>Array.isArray(value[k]))&&value.profile&&value.style)return value;}catch{}return freshState();}
export function ensureProfile(state){state.ownerId ||= uid('local');state.styleVersion ||= 1;state.styleHistory ||= [{version:1,style:structuredClone(state.style),at:new Date().toISOString(),reason:'Initial style'}];state.feedback ||= [];return state;}
export function createVariants(story,style){
 const base=createOutline(story,style);
 const original=String(story.body).trim();
 const sentences=original.split(/(?<=[.!?])\s+|\n+/).map(s=>s.trim()).filter(Boolean);
 const body=style.traits.includes('Short paragraphs')?sentences.join('\n\n'):original;
 const prefix=style.structure==='lesson'?`${story.title}\n\n`:'';
 const suffix=style.traits.includes('Curious questions')?'\n\nWhat has your experience been?':'';
 return [{...base,title:`${story.title} · Natural`,body:`${prefix}${body}${suffix}`,variant:'Natural rhythm'},
 {...base,id:uid('draft'),title:`${story.title} · Scannable`,body:`${prefix}${sentences.map(s=>`• ${s}`).join('\n\n')}${suffix}`,variant:'A scannable list'},
 {...base,id:uid('draft'),title:`${story.title} · Numbered`,body:`${prefix}${sentences.map((s,i)=>`${i+1}. ${s}`).join('\n\n')}${suffix}`,variant:'Numbered notes'}];
}
export function addFeedback(state,draftId,data){if(!state.drafts.some(d=>d.id===draftId))throw Error('Draft not found.');if(!['like','dislike','edited'].includes(data.rating))throw Error('Choose how this version felt.');const item={id:uid('feedback'),ownerId:state.ownerId,draftId,rating:data.rating,reasons:[...(data.reasons||[])],note:String(data.note||'').trim().slice(0,1500),at:new Date().toISOString()};state.feedback.push(item);return item;}
export function proposeStyle(state,feedback){const next=structuredClone(state.style);const changes=[];for(const reason of feedback.reasons){if(reason==='shorter'){if(!next.traits.includes('Short paragraphs'))next.traits.push('Short paragraphs');changes.push('Use shorter paragraphs.');}if(reason==='natural'){next.structure='story';next.tone='Warm & grounded';changes.push('Start with the story in your own words.');}if(reason==='headline'){next.structure='lesson';changes.push('Put your story title first.');}if(reason==='no_question'){next.traits=next.traits.filter(t=>t!=='Curious questions');changes.push('Do not add a closing question by default.');}if(reason==='question'){if(!next.traits.includes('Curious questions'))next.traits.push('Curious questions');changes.push('End with an open question by default.');}}return {style:next,changes,note:feedback.note};}
export function applyStyle(state,next,reason){ensureProfile(state);state.style=structuredClone(next);state.styleVersion++;state.styleHistory.push({version:state.styleVersion,style:structuredClone(next),at:new Date().toISOString(),reason});return state.styleVersion;}
export function exportSkill(state){ensureProfile(state);return `# Personal writing profile\n\nOwner: ${state.profile.name||'Local workspace owner'}\nPrototype workspace ID: ${state.ownerId}\nVersion: ${state.styleVersion}\n\n## Voice\nTone: ${state.style.tone}\nStructure: ${state.style.structure==='lesson'?'Story title first':'Story first'}\nTraits: ${state.style.traits.join(', ')}\nAvoid: ${state.style.avoid}\n\n## Grounding rules\nUse only this owner's approved facts and authorized writing. Never borrow a reference creator's life experiences. Ask when facts are missing. Keep feedback private to this owner. This local prototype is not authenticated and this export contains no account credentials.\n\n## Reference bookmarks\n${state.references.map(r=>`- ${r.name}${r.url?` (${r.url})`:''}: ${r.notes||'No style notes yet.'}`).join('\n')||'No bookmarks yet.'}\n\n## Personal feedback\n${state.feedback.filter(f=>f.ownerId===state.ownerId).map(f=>`- ${f.rating}: ${f.reasons.join(', ')}. ${f.note}`).join('\n')||'No feedback yet.'}\n\n## Runtime limits\nNo AI model is connected. Template previews use structure, paragraph rhythm, and closing-question controls; tone and free-text feedback are saved for a future approved model. This is not automatic creator analysis.\n`;}
